using System;using System.Collections.Generic;using System.Linq;using UnityEditor;using UnityEngine;using Object=UnityEngine.Object;
// Offline AK conversion. Source clips are immutable; arms, mount and mechanisms each have one owner.
public static class AKFullReloadConversion {
const string Folder="Assets/Game/Animations/Weapons/Reloads/SharedConversions/";
const string Legacy="Assets/Game/Animations/Weapons/Scaled/legacy-ak12/";
static Transform Find(GameObject g,string n)=>g.GetComponentsInChildren<Transform>(true).First(t=>t.name==n);
static AnimationClip State(SoldierWeaponView v,string action)=>WeaponAnimationSource.State(v.animationOverride,"Base Layer",action);
sealed class Rig:IDisposable{public GameObject root;public Transform gun,mount;Transform[] nodes;(Vector3 p,Quaternion q,Vector3 s)[] rest;public Rig(SoldierWeaponView v,bool source){root=Object.Instantiate(v.sharedFirstPersonRig);foreach(var a in root.GetComponentsInChildren<Animator>(true))a.enabled=false;mount=root.transform.Find(source?"ViewMotion/WeaponMotion":v.sharedWeaponMountPath);gun=source?new GameObject("SourceWeapon").transform:Object.Instantiate(v,mount,false).transform;gun.SetParent(mount,false);gun.name="SourceWeapon";gun.SetLocalPositionAndRotation(source?new Vector3(.08398786f,1.5175846f,.21859884f):v.mountPosition,source?new Quaternion(.0000003910396f,.70710653f,.7071071f,.00000040294714f):v.mountRotation);gun.localScale=source?new Vector3(.938632f,.9386318f,.9386318f):v.mountScale;nodes=root.GetComponentsInChildren<Transform>(true);rest=nodes.Select(t=>(t.localPosition,t.localRotation,t.localScale)).ToArray();}public void Reset(){for(int i=0;i<nodes.Length;i++){nodes[i].SetLocalPositionAndRotation(rest[i].p,rest[i].q);nodes[i].localScale=rest[i].s;}}public void Dispose()=>Object.DestroyImmediate(root);}
static void Solve(Transform upper,Transform fore,Transform hand,Vector3 position,Quaternion rotation,Vector3 pole){var p=upper.position;float a=Vector3.Distance(p,fore.position),b=Vector3.Distance(fore.position,hand.position);var d=position-p;float length=Mathf.Clamp(d.magnitude,Mathf.Abs(a-b)+.0001f,a+b-.0001f);var axis=d.normalized;var bend=Vector3.ProjectOnPlane(pole-p,axis).normalized;if(bend.sqrMagnitude<.01f)bend=Vector3.ProjectOnPlane(Vector3.up,axis).normalized;float x=(a*a-b*b+length*length)/(2*length);var elbow=p+axis*x+bend*Mathf.Sqrt(Mathf.Max(0,a*a-x*x));upper.rotation=Quaternion.FromToRotation(fore.position-p,elbow-p)*upper.rotation;fore.rotation=Quaternion.FromToRotation(hand.position-fore.position,p+axis*length-fore.position)*fore.rotation;hand.rotation=rotation;}
static Vector3 Center(Transform mag,Transform gun){var pts=new List<Vector3>();foreach(var skin in gun.GetComponentsInChildren<SkinnedMeshRenderer>(true)){int k=Array.IndexOf(skin.bones,mag);if(k<0)continue;var mesh=skin.sharedMesh;var weights=mesh.boneWeights;pts.AddRange(mesh.vertices.Where((v,i)=>weights[i].boneIndex0==k&&weights[i].weight0>.9f).Select(v=>mag.InverseTransformPoint((mag.localToWorldMatrix*mesh.bindposes[k]).MultiplyPoint3x4(v))));}if(pts.Count==0)foreach(var f in mag.GetComponentsInChildren<MeshFilter>(true))pts.AddRange(f.sharedMesh.vertices.Select(v=>mag.InverseTransformPoint(f.transform.TransformPoint(v))));var bounds=new Bounds(pts[0],Vector3.zero);foreach(var point in pts)bounds.Encapsulate(point);return bounds.center;}
// The AK family's charging tab protrudes along negative weapon X. Fit the outer tab, not the bolt pivot.
static Vector3 ChargingContact(Transform bone,Transform gun){var points=new List<Vector3>();foreach(var skin in gun.GetComponentsInChildren<SkinnedMeshRenderer>(true)){int k=Array.IndexOf(skin.bones,bone);if(k<0)continue;var mesh=skin.sharedMesh;var weights=mesh.boneWeights;points.AddRange(mesh.vertices.Where((v,i)=>weights[i].boneIndex0==k&&weights[i].weight0>.9f).Select(v=>gun.InverseTransformPoint((bone.localToWorldMatrix*mesh.bindposes[k]).MultiplyPoint3x4(v))));}foreach(var f in bone.GetComponentsInChildren<MeshFilter>(true))points.AddRange(f.sharedMesh.vertices.Select(v=>gun.InverseTransformPoint(f.transform.TransformPoint(v))));if(points.Count==0)throw new InvalidOperationException("No charging-tab geometry for "+gun.name);float edge=points.Min(v=>v.x);var tab=points.Where(v=>v.x<edge+.004f).ToArray();var contact=tab.Aggregate(Vector3.zero,(a,b)=>a+b)/tab.Length;contact.x+=.003f;return bone.InverseTransformPoint(gun.TransformPoint(contact));}
static Vector3 Relative(Transform frame,Vector3 point)=>Quaternion.Inverse(frame.rotation)*(point-frame.position);
[MenuItem("Tools/Weapons/Rebuild Polygon AK Full Reloads")]
public static void Rebuild()=>Run();
public static object Run(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new InvalidOperationException("Exit Play Mode before conversion.");var catalog=AssetDatabase.LoadAssetAtPath<WeaponCatalog>("Assets/Game/Definitions/Weapons/Catalogs/WeaponCatalog.asset");var sourceIdle=AssetDatabase.LoadAssetAtPath<AnimationClip>(Legacy+"Gameplay_Idle_UE4.anim");var sourceReload=AssetDatabase.LoadAssetAtPath<AnimationClip>(Legacy+"Gameplay_Reload_UE4.anim");var native=catalog.entries.Single(e=>e.weapon.displayName=="AK-12 [FPS Pack] (Scaled)");using var nr=new Rig(native.firstPersonPrefab,false);State(native.firstPersonPrefab,"Idle").SampleAnimation(nr.root,0);var nm=Find(nr.gun.gameObject,"Mag");var magQ=nm.rotation;var nativeGunIdleQ=nr.gun.rotation;var nc=Center(nm,nr.gun);var nt=WeaponAnimationSource.State(native.firstPersonPrefab.ReloadAnimation(false),"Base Layer","Reload");nt.SampleAnimation(nr.root,nt.length*.5f);var nf=nm.rotation*Quaternion.Inverse(magQ)*nativeGunIdleQ;var nh=Find(nr.root,"hand_l");var contactP=Quaternion.Inverse(nf)*(nh.position-nm.TransformPoint(nc));var contactQ=Quaternion.Inverse(nf)*nh.rotation;var contactF=nr.root.GetComponentsInChildren<Transform>(true).Where(t=>t.name.EndsWith("_l")&&new[]{"thumb_","index_","middle_","ring_","pinky_"}.Any(t.name.StartsWith)).ToDictionary(t=>t.name,t=>t.localRotation);
var reports=new List<object>();foreach(var job in new[]{("AK-12","AK12"),("AK-74","AK74"),("AKM","AKM")}){var e=catalog.entries.Single(e=>e.weapon.displayName==job.Item1);var view=e.firstPersonPrefab;string folder=Folder+job.Item2+"/";using var source=new Rig(view,true);using var target=new Rig(view,false);var idle=State(view,"Idle");sourceIdle.SampleAnimation(source.root,0);idle.SampleAnimation(target.root,0);var sourceGunP=source.gun.position;var sourceGunQ=source.gun.rotation;var gunP=target.gun.position;var gunQ=target.gun.rotation;var sourceToTargetAxes=Quaternion.Inverse(gunQ)*sourceGunQ;var gunLocal=(p:target.gun.localPosition,q:target.gun.localRotation,s:target.gun.localScale);var skeleton=Find(target.root,"SourceArms");var rootPose=(skeleton.localPosition,skeleton.localRotation,skeleton.localScale);
var sh=new[]{Find(source.root,"hand_l"),Find(source.root,"hand_r")};var th=new[]{Find(target.root,"hand_l"),Find(target.root,"hand_r")};var se=new[]{Find(source.root,"lowerarm_l"),Find(source.root,"lowerarm_r")};var te=new[]{Find(target.root,"lowerarm_l"),Find(target.root,"lowerarm_r")};var oldHand=sh.Select(t=>Relative(source.gun,t.position)).ToArray();var newHand=th.Select(t=>Relative(target.gun,t.position)).ToArray();var oldQ=sh.Select(t=>Quaternion.Inverse(source.gun.rotation)*t.rotation).ToArray();var newQ=th.Select(t=>Quaternion.Inverse(target.gun.rotation)*t.rotation).ToArray();var oldElbow=se.Select(t=>Relative(source.gun,t.position)).ToArray();var newElbow=te.Select(t=>Relative(target.gun,t.position)).ToArray();
var fingers=skeleton.GetComponentsInChildren<Transform>(true).Where(t=>new[]{"thumb_","index_","middle_","ring_","pinky_"}.Any(t.name.StartsWith)).ToArray();var oldF=fingers.Select(t=>Find(source.root,t.name).localRotation).ToArray();var newF=fingers.Select(t=>t.localRotation).ToArray();var sf=fingers.Select(t=>Find(source.root,t.name)).ToArray();
var mag=Find(target.gun.gameObject,job.Item2=="AKM"?"magazine":"Mag");AssetDatabase.LoadAssetAtPath<AnimationClip>(folder+"IdleMechanisms.anim").SampleAnimation(target.root,0);var charge=Find(target.gun.gameObject,job.Item2=="AKM"?"reload":"Charge");var chargeContact=ChargingContact(charge,target.gun);var index=Find(target.root,"index_03_r");var magRestQ=mag.rotation;var mc=Center(mag,target.gun);var mechanisms=AssetDatabase.LoadAssetAtPath<AnimationClip>(folder+"FullMechanisms.anim");var boneRoot=Find(target.root,"root");var nodes=boneRoot.GetComponentsInChildren<Transform>(true).Where(t=>t!=target.gun&&!t.IsChildOf(target.gun)).Concat(new[]{target.root.transform.Find("ViewMotion"),target.root.transform.Find("ViewMotion/WeaponMotion"),skeleton,target.gun}).Distinct().ToArray();var rest=nodes.Select(t=>(p:t.localPosition,q:t.localRotation,s:t.localScale)).ToArray();var tracks=nodes.Select(t=>new TpsPartsAdapter.PoseTrack{source=t,path=AnimationUtility.CalculateTransformPath(t,target.root.transform)}).ToArray();int count=Mathf.CeilToInt(sourceReload.length*120);var times=new float[count+1];float stableRoot=0,endpointError=0,maxChargingError=0,maxSettleError=0;
for(int i=0;i<=count;i++){float t=sourceReload.length*i/count;times[i]=t;source.Reset();sourceIdle.SampleAnimation(source.root,0);sourceReload.SampleAnimation(source.root,t);target.Reset();idle.SampleAnimation(target.root,0);float blend=Mathf.SmoothStep(0,1,t/.23f)*Mathf.SmoothStep(0,1,(sourceReload.length-.12f-t)/.30f);
// Rebase once in metres and rigid rotations; never copy old parent transforms or animated scale.
// Preserve the source motion's camera-space axes. Mesh registration changes weapon-local axes.
var movement=source.gun.position-sourceGunP;var rotation=source.gun.rotation*Quaternion.Inverse(sourceGunQ);var desiredP=gunP+movement;var desiredQ=rotation*gunQ;desiredP=Vector3.Lerp(gunP,desiredP,blend);desiredQ=Quaternion.Slerp(gunQ,desiredQ,blend);
var desired=Matrix4x4.TRS(desiredP,desiredQ,target.gun.lossyScale);var local=Matrix4x4.TRS(gunLocal.p,gunLocal.q,gunLocal.s);var mountFrame=desired*local.inverse;target.mount.SetPositionAndRotation(mountFrame.GetColumn(3),mountFrame.rotation);target.gun.SetLocalPositionAndRotation(gunLocal.p,gunLocal.q);target.gun.localScale=gunLocal.s;
for(int side=0;side<2;side++){var delta=sourceToTargetAxes*(Relative(source.gun,sh[side].position)-oldHand[side]);var pose=newHand[side]+delta;var q=sourceToTargetAxes*(Quaternion.Inverse(source.gun.rotation)*sh[side].rotation)*Quaternion.Inverse(oldQ[side])*Quaternion.Inverse(sourceToTargetAxes)*newQ[side];var elbow=Vector3.Lerp(newElbow[side],newElbow[side]+sourceToTargetAxes*(Relative(source.gun,se[side].position)-oldElbow[side]),blend);var p=target.gun.position+target.gun.rotation*Vector3.Lerp(newHand[side],pose,blend);var hq=target.gun.rotation*Quaternion.Slerp(newQ[side],q,blend);string s=side==0?"l":"r";Solve(Find(target.root,"upperarm_"+s),te[side],th[side],p,hq,target.gun.position+target.gun.rotation*elbow);}
for(int k=0;k<fingers.Length;k++)fingers[k].localRotation=Quaternion.Slerp(newF[k],sf[k].localRotation*Quaternion.Inverse(oldF[k])*newF[k],blend);
// Magazine contact is authored against the actual moving part, using the current hand's calibrated grasp.
mechanisms.SampleAnimation(target.root,t);float phase=t/sourceReload.length;float grasp=Mathf.SmoothStep(0,1,Mathf.InverseLerp(.05f,.12f,phase))*(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(.54f,.64f,phase)));var magFrame=mag.rotation*Quaternion.Inverse(magRestQ)*gunQ;Solve(Find(target.root,"upperarm_l"),te[0],th[0],Vector3.Lerp(th[0].position,mag.TransformPoint(mc)+magFrame*contactP,grasp),Quaternion.Slerp(th[0].rotation,magFrame*contactQ,grasp),te[0].position);foreach(var finger in fingers)if(contactF.TryGetValue(finger.name,out var fq))finger.localRotation=Quaternion.Slerp(finger.localRotation,fq,grasp);
// Fit only the charging interval; retain the accepted weapon/magazine motion and hand rotation.
float charging=Mathf.SmoothStep(0,1,Mathf.InverseLerp(.598f,.635f,phase))*(1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(.708f,.730f,phase)));var contact=charge.TransformPoint(chargeContact);if(charging>0){var goal=th[1].position+(contact-index.position)*charging;Solve(Find(target.root,"upperarm_r"),te[1],th[1],goal,th[1].rotation,te[1].position);if(charging>.9999f)maxChargingError=Mathf.Max(maxChargingError,Vector3.Distance(index.position,contact));}
if(blend<=.000001f)for(int k=0;k<nodes.Length;k++){endpointError=Mathf.Max(endpointError,Vector3.Distance(nodes[k].localPosition,rest[k].p));nodes[k].SetLocalPositionAndRotation(rest[k].p,rest[k].q);nodes[k].localScale=rest[k].s;}
if(t>=sourceReload.length-.1f)for(int k=0;k<nodes.Length;k++)maxSettleError=Mathf.Max(maxSettleError,Vector3.Distance(nodes[k].localPosition,rest[k].p));stableRoot=Mathf.Max(stableRoot,Vector3.Distance(skeleton.localPosition,rootPose.localPosition));foreach(var track in tracks)track.Sample();}
var clip=new AnimationClip{frameRate=120};foreach(var track in tracks)TpsPartsAdapter.Write(clip,track,times);clip=WeaponReloadBuilder.Save(clip,folder+"FullFPS.anim");var parts=AssetDatabase.LoadAssetAtPath<AnimationClip>(folder+"FullMechanisms.anim");var overlap=AnimationUtility.GetCurveBindings(clip).Select(b=>b.path+":"+b.propertyName).Intersect(AnimationUtility.GetCurveBindings(parts).Select(b=>b.path+":"+b.propertyName)).ToArray();if(overlap.Length>0||stableRoot>.00001f)throw new Exception("Transform ownership invariant failed");
var combined=Object.Instantiate(clip);foreach(var b in AnimationUtility.GetCurveBindings(parts))AnimationUtility.SetEditorCurve(combined,b,AnimationUtility.GetEditorCurve(parts,b));var idleCombined=Object.Instantiate(idle);var ip=AssetDatabase.LoadAssetAtPath<AnimationClip>(folder+"IdleMechanisms.anim");foreach(var b in AnimationUtility.GetCurveBindings(ip))AnimationUtility.SetEditorCurve(idleCombined,b,AnimationUtility.GetEditorCurve(ip,b));var proof=ScriptableObject.CreateInstance<WeaponAnimationConversionProof>();try{proof.originalProportions=true;proof.source=proof.converted=e;proof.idle=idleCombined;proof.reload=combined;proof.thirdPersonSourceController=e.weapon.thirdPerson;proof.thirdPersonSourceParts=e.weapon.fullReload.thirdPersonParts;TpsAnimationAdapter.BuildReload(proof,folder+"FullBody");AssetDatabase.DeleteAsset(folder+"FullBody/ReloadParts.anim");}finally{Object.DestroyImmediate(proof);Object.DestroyImmediate(combined);Object.DestroyImmediate(idleCombined);}reports.Add(new{weapon=job.Item1,rootDrift=stableRoot,endpointError,overlappingBindings=overlap.Length,magazineUntouched=true,chargingIndexErrorMeters=maxChargingError,endHoldErrorMeters=maxSettleError});}AssetDatabase.SaveAssets();return reports;}}

